    if (jobs && jobs.children.length >= 10 && !text.includes('Loading')) {
      resolve({ children: jobs.children.length, preview: text.slice(0, 60) });
      return;
    }
    if (Date.now() - start > 25000) {
      resolve({ timeout: true, children: jobs && jobs.children.length, preview: text.slice(0, 80) });
