(() => {
  const btn = document.getElementById('filterBtn');
  const samples = [];
  const start = Date.now();
  const stamp = (tag) => {
    const svg = btn.querySelector('svg');
    const cs = svg ? getComputedStyle(svg) : null;
    samples.push({
      tag,
      ms: Date.now() - start,
      name: btn.textContent.replace(/\s+/g, ' ').trim(),
      after: getComputedStyle(btn, '::after').content,
      cls: btn.className,
      busy: btn.getAttribute('aria-busy'),
      borderTop: cs && cs.borderTopColor,
      anim: cs && cs.animationName,
      cursor: getComputedStyle(btn).cursor,
    });
  };
  stamp('before');
  document.getElementById('hidePositionApplied').click();
  stamp('after-click');
  return new Promise((resolve) => {
    const iv = setInterval(() => {
      stamp('tick');
      if (Date.now() - start > 2500 || btn.getAttribute('aria-busy') !== 'true') {
        clearInterval(iv);
        stamp('end');
        resolve(samples);
      }
    }, 200);
  });
})()

